@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
     *  whether a statement bound the claim, statedDue the figure it bound it to (null when none);
     *  corrects is the number of the claim a correction corrects (null when it is not one); roundsBy
     *  is the date its live figures round by against the sheet's policy date (its own date, or for a
     *  correction the date of the claim it corrects); dueBy is the date it is due by, fixed when it was
     *  added; log is its status log, oldest first, one line per status it has had; deferredUntil is
     *  the date it was deferred until (null when it never was); proofs is how many proofs were added
     *  to it; splitFrom is the number of the claim it was split off (null when it was not); lockedBy is
     *  the user whose open editor locks it (null when no one's does); lateEntry is whether it was
     *  added while its period was soft-closed; remindedOn is the last day a reminder was written for it
     *  (null when none was); ref is its external reference (null when it has none); tags are its tags,
     *  sorted (empty when it has none); voidReason is the reason it was voided with (null when none
     *  was given); comments are its comments, oldest first, each as <user> on <date>: <text>; batch
     *  is the number of the settle batch that settled it (null when a bulk settle did not); lines are
     *  its lines, oldest first, each as <label> <qty> x <unit> (empty when it has none). */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, LocalDate roundsBy, LocalDate dueBy, List<String> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry,
            LocalDate remindedOn, String ref, List<String> tags, String voidReason, List<String> comments,
            Long batch, List<String> lines) {
        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments) {
            return of(claim, roundsBy, log, comments, List.of());
        }

        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments,
                List<String> lines) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                    claim.getCorrects(), roundsBy, claim.getDueBy(), log, claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                    claim.getVoidReason(), comments, claim.getBatch(), lines);
        }
    }

    /** A claim's fields: an amount with up to two decimals (a negative one is a correction), a date
     *  (blank takes the sheet's today), a note (may be empty) and, for a correction, the number of
     *  the claim it corrects, an external reference (blank: none) and tags, comma separated (blank:
     *  none). */
    public record ClaimRequest(
            @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 2000) String note,
            @Size(max = 255) String corrects,
            @Size(max = 255) String ref,
            @Size(max = 2000) String tags) {
    }

    /** The name of the sheet's claim template a claim is added from. */
    public record FromTemplateRequest(@NotBlank @Size(max = 255) String template) {
    }

    /** A line added to a DRAFT claim: a label, a whole quantity of at least 1 and a unit amount with
     *  up to two decimals. */
    public record LineRequest(
            @NotBlank @Size(max = 255) String label,
            @NotNull @Min(1) @Max(1_000_000) Integer qty,
            @NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal unit) {
    }

    /** The date an OPEN claim is deferred until. */
    public record DeferRequest(@NotNull LocalDate until) {
    }

    /** The reason a claim is voided with, chosen from the sheet's list; blank or absent for none. */
    public record VoidRequest(@Size(max = 255) String reason) {
    }

    /** A comment on a claim: its text, which must not be blank. */
    public record CommentRequest(@Size(max = 2000) String text) {
    }

    /** Why a steward rejects a PENDING claim. */
    public record RejectRequest(@NotBlank @Size(max = 500) String reason) {
    }

    /** The new date of an OPEN or PENDING claim. */
    public record RedateRequest(@NotNull LocalDate date) {
    }

import { Component, input } from '@angular/core';

export interface GradeSummary {
  grade: string;
  /** How many people not retired are on the grade on the sheet's today. */
  count: number;
  /** Their due-totals added up, skipping those with no figure (two decimals). */
  dueTotal: string;
  /** How many of them are active. */
  active: number;
}

export interface PeriodSummary {
  name: string;
  /** The due-total the period's row shows (two decimals). */
  dueTotal: string;
  /** This period's due-total minus that of the period before it by start date (two decimals);
   *  blank for the earliest period. */
  change: string;
}

export interface ClassicPeriodSummary {
  name: string;
  /** The period's due-total counting each claim by its status now; a closed period's figure fixed
   *  when it closed (two decimals). */
  dueTotal: string;
}

export interface StatusSummary {
  status: string;
  /** How many of the sheet's claims have the status. */
  count: number;
}

export interface VoidReasonSummary {
  reason: string;
  /** How many of the sheet's VOID claims were voided with the reason. */
  count: number;
}

// The sheet in figures, each worked out from what the list shows: per grade, per period and per
// claim status and void reason; and beside it the classic summary.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <table>
        <caption>By grade</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">People</th>
            <th scope="col">Due</th>
            <th scope="col">Active</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By period</caption>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">Due</th>
            <th scope="col">Change</th>
          </tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
              <td [attr.data-testid]="'summary-period-' + p.name + '-change'">{{ p.change }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By status</caption>
        <thead>
          <tr>
            <th scope="col">Status</th>
            <th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By void reason</caption>
        <thead>
          <tr>
            <th scope="col">Reason</th>
            <th scope="col">Voided claims</th>
          </tr>
        </thead>
        <tbody>
          @for (v of voids(); track v.reason) {
            <tr>
              <th scope="row">{{ v.reason }}</th>
              <td [attr.data-testid]="'summary-void-' + v.reason + '-count'">{{ v.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
    <section aria-labelledby="classic-summary-heading">
      <h2 id="classic-summary-heading">Classic summary</h2>
      <table>
        <caption>By period</caption>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">Due</th>
          </tr>
        </thead>
        <tbody>
          @for (p of classicPeriods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'classic-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <p>Sheet due-total: <span data-testid="classic-due-total">{{ classicDueTotal() }}</span></p>
    </section>
  `,
})
export class Summary {
  readonly grades = input.required<GradeSummary[]>();
  readonly periods = input.required<PeriodSummary[]>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly voids = input.required<VoidReasonSummary[]>();
  readonly classicPeriods = input.required<ClassicPeriodSummary[]>();
  readonly classicDueTotal = input.required<string>();
}

